[CmdletBinding()]
param([Parameter(Mandatory)][ValidateSet('joint-plan','joint-preview','joint-request-approval','joint-validate','joint-start','joint-reconcile','joint-fail')][string]$Operation,[Parameter(Mandatory)][string]$TaskId,[string]$AdapterId,[string]$SupervisorRunId,[string]$ApprovalId,[string]$ErrorDetails,[ValidateRange(1,1440)][int]$ExpiryMinutes=30,[string]$StoreRoot=(Join-Path $PSScriptRoot 'Store'),[switch]$DryRun)
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'Repato.JointApproval.psm1') -Force -WarningAction SilentlyContinue
$r=switch($Operation){'joint-plan'{New-JointPlan $StoreRoot $TaskId $AdapterId -DryRun:$DryRun};'joint-preview'{Get-JointPreview $StoreRoot $TaskId $ApprovalId};'joint-request-approval'{Request-JointApproval $StoreRoot $TaskId $SupervisorRunId $ExpiryMinutes};'joint-validate'{Validate-JointApproval $StoreRoot $TaskId $ApprovalId};'joint-start'{Start-JointExecution $StoreRoot $TaskId $ApprovalId -DryRun:$DryRun};'joint-reconcile'{Reconcile-Joint $StoreRoot $TaskId};'joint-fail'{Fail-Joint $StoreRoot $TaskId $ApprovalId $ErrorDetails}};$r|ConvertTo-Json -Depth 20
